define(["core/ajax","core/notification"],function(Ajax,Notification){const init=function(bookflowId){document.querySelectorAll(".bookflow-content video").forEach(function(media){const block=media.closest(".bookflow-content");let lastSent=-1;const send=function(force){if(!media.duration||!Number.isFinite(media.duration)){return}const percentage=Math.min(100,media.currentTime/media.duration*100);const bucket=Math.floor(percentage/5);if(!force&&bucket===lastSent){return}lastSent=bucket;Ajax.call([{methodname:"mod_bookflow_mark_content_completed",args:{bookflowid:bookflowId,contentid:Number(block.dataset.contentId),metric:percentage,details:JSON.stringify({watchedSeconds:Math.floor(media.currentTime),duration:Math.floor(media.duration)})}}])[0].catch(function(error){if(force){Notification.exception(error)}})};media.addEventListener("timeupdate",function(){send(false)});media.addEventListener("ended",function(){send(true)})})};return{init:init}});